export const SECURITY_POLICIES = {"items":[{"kind":"acceptable_use","name":"Acceptable use","purpose":"How everyone uses work devices, email and data safely.","version":4,"versions":2,"published":{"n":2,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-25T09:00:00+00:00","published_at":"2026-09-26T09:00:00+00:00","published_by":"Sarah Vale"},"draft":null,"acks":{"done":2,"total":7,"missing":["Dan Okafor","Dev Patel","Grace Lin","Mark Ellis","Zoe Clarke"]},"my_ack":true},{"kind":"passwords","name":"Passwords and two-step sign-in","purpose":"How everyone signs in safely, and what to do when a password leaks.","version":2,"versions":1,"published":{"n":1,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-09T09:00:00+00:00","published_at":"2026-09-11T09:00:00+00:00","published_by":"Sarah Vale"},"draft":null,"acks":{"done":5,"total":7,"missing":["Dev Patel","Mark Ellis"]},"my_ack":true},{"kind":"incident_response","name":"Incident response","purpose":"Who to tell and what to do first when something goes wrong.","version":1,"versions":1,"published":null,"draft":{"n":1,"source":"template","status":"draft","by_name":"Sarah Vale","at":"2026-09-29T09:00:00+00:00","published_at":null,"published_by":null},"acks":{"done":0,"total":0,"missing":[]},"my_ack":false},{"kind":"data_retention","name":"Data retention","purpose":"How long each kind of record is kept, and how it is deleted.","version":0,"versions":0,"published":null,"draft":null,"acks":{"done":0,"total":0,"missing":[]},"my_ack":false}],"published":2,"total":4,"ack_pct":50,"ai":false,"members":7};
export const POLICY_DETAILS = {"acceptable_use":{"kind":"acceptable_use","name":"Acceptable use","purpose":"How everyone uses work devices, email and data safely.","version":4,"versions":2,"published":{"n":2,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-25T09:00:00+00:00","published_at":"2026-09-26T09:00:00+00:00","published_by":"Sarah Vale"},"draft":null,"acks":{"done":2,"total":7,"missing":["Dan Okafor","Dev Patel","Grace Lin","Mark Ellis","Zoe Clarke"]},"my_ack":true,"history":[{"n":2,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-25T09:00:00+00:00","published_at":"2026-09-26T09:00:00+00:00","published_by":"Sarah Vale","sections":[{"heading":"Why we have this policy","items":["This policy says how everyone at Harbour & Vale Logistics uses work devices, email and data safely.","It protects our customers, our money and each other."]},{"heading":"Who it covers","items":["Everyone who works for us, including part-time staff, contractors and volunteers.","Every device used for work, including your own phone if it has work email on it."]},{"heading":"Using work devices","items":["Lock your screen when you step away.","Let updates install. Do not put them off for more than a few days.","Do not let anyone else, including family, use a work device.","Only install apps that an owner has agreed to."]},{"heading":"Email and the internet","items":["Do not open links or files you did not expect, even from people you know.","Check any request to change bank details or pay a new account by phone, using a number you already have.","Do not use your work email to sign up for personal things."]},{"heading":"Customer and business data","items":["Keep customer data only in the systems we chose (gmail, hubspot, slack, xero, zendesk).","Do not copy it to personal accounts, personal email or USB sticks.","Share files only with the people who need them."]},{"heading":"Reporting a problem","items":["If something looks wrong, tell an owner of Harbour & Vale Logistics straight away. You will never be blamed for reporting."]},{"heading":"If the policy is not followed","items":["Breaking this policy on purpose may lead to action under our disciplinary process."]},{"heading":"Review","items":["An owner reads this policy again every year, and after any incident."]}],"text":"## Why we have this policy\n- This policy says how everyone at Harbour & Vale Logistics uses work devices, email and data safely.\n- It protects our customers, our money and each other.\n\n## Who it covers\n- Everyone who works for us, including part-time staff, contractors and volunteers.\n- Every device used for work, including your own phone if it has work email on it.\n\n## Using work devices\n- Lock your screen when you step away.\n- Let updates install. Do not put them off for more than a few days.\n- Do not let anyone else, including family, use a work device.\n- Only install apps that an owner has agreed to.\n\n## Email and the internet\n- Do not open links or files you did not expect, even from people you know.\n- Check any request to change bank details or pay a new account by phone, using a number you already have.\n- Do not use your work email to sign up for personal things.\n\n## Customer and business data\n- Keep customer data only in the systems we chose (gmail, hubspot, slack, xero, zendesk).\n- Do not copy it to personal accounts, personal email or USB sticks.\n- Share files only with the people who need them.\n\n## Reporting a problem\n- If something looks wrong, tell an owner of Harbour & Vale Logistics straight away. You will never be blamed for reporting.\n\n## If the policy is not followed\n- Breaking this policy on purpose may lead to action under our disciplinary process.\n\n## Review\n- An owner reads this policy again every year, and after any incident."},{"n":1,"source":"template","status":"retired","by_name":"Sarah Vale","at":"2026-08-02T09:00:00+00:00","published_at":"2026-08-03T09:00:00+00:00","published_by":"Sarah Vale","sections":[{"heading":"Why we have this policy","items":["This policy says how everyone at Harbour & Vale Logistics uses work devices, email and data safely.","It protects our customers, our money and each other."]},{"heading":"Who it covers","items":["Everyone who works for us, including part-time staff, contractors and volunteers.","Every device used for work, including your own phone if it has work email on it."]},{"heading":"Using work devices","items":["Lock your screen when you step away.","Let updates install. Do not put them off for more than a few days.","Do not let anyone else, including family, use a work device.","Only install apps that an owner has agreed to."]},{"heading":"Email and the internet","items":["Do not open links or files you did not expect, even from people you know.","Check any request to change bank details or pay a new account by phone, using a number you already have.","Do not use your work email to sign up for personal things."]},{"heading":"Customer and business data","items":["Keep customer data only in the systems we chose (gmail, hubspot, slack, xero, zendesk).","Do not copy it to personal accounts, personal email or USB sticks.","Share files only with the people who need them."]},{"heading":"Reporting a problem","items":["If something looks wrong, tell an owner of Harbour & Vale Logistics straight away. You will never be blamed for reporting."]},{"heading":"If the policy is not followed","items":["Breaking this policy on purpose may lead to action under our disciplinary process."]},{"heading":"Review","items":["An owner reads this policy again every year, and after any incident."]}],"text":"## Why we have this policy\n- This policy says how everyone at Harbour & Vale Logistics uses work devices, email and data safely.\n- It protects our customers, our money and each other.\n\n## Who it covers\n- Everyone who works for us, including part-time staff, contractors and volunteers.\n- Every device used for work, including your own phone if it has work email on it.\n\n## Using work devices\n- Lock your screen when you step away.\n- Let updates install. Do not put them off for more than a few days.\n- Do not let anyone else, including family, use a work device.\n- Only install apps that an owner has agreed to.\n\n## Email and the internet\n- Do not open links or files you did not expect, even from people you know.\n- Check any request to change bank details or pay a new account by phone, using a number you already have.\n- Do not use your work email to sign up for personal things.\n\n## Customer and business data\n- Keep customer data only in the systems we chose (gmail, hubspot, slack, xero, zendesk).\n- Do not copy it to personal accounts, personal email or USB sticks.\n- Share files only with the people who need them.\n\n## Reporting a problem\n- If something looks wrong, tell an owner of Harbour & Vale Logistics straight away. You will never be blamed for reporting.\n\n## If the policy is not followed\n- Breaking this policy on purpose may lead to action under our disciplinary process.\n\n## Review\n- An owner reads this policy again every year, and after any incident."}],"outline":["Why we have this policy","Who it covers","Using work devices","Email and the internet","Customer and business data","Reporting a problem","If the policy is not followed","Review"]},"passwords":{"kind":"passwords","name":"Passwords and two-step sign-in","purpose":"How everyone signs in safely, and what to do when a password leaks.","version":2,"versions":1,"published":{"n":1,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-09T09:00:00+00:00","published_at":"2026-09-11T09:00:00+00:00","published_by":"Sarah Vale"},"draft":null,"acks":{"done":5,"total":7,"missing":["Dev Patel","Mark Ellis"]},"my_ack":true,"history":[{"n":1,"source":"template","status":"published","by_name":"Sarah Vale","at":"2026-09-09T09:00:00+00:00","published_at":"2026-09-11T09:00:00+00:00","published_by":"Sarah Vale","sections":[{"heading":"Why we have this policy","items":["Stolen and guessed passwords are a common way into a business. These rules make that much harder."]},{"heading":"Passwords","items":["Use a different password for every work account.","Make each one long: three random words together is a good way (NCSC advice).","Keep them in a password manager, not in a notebook, a file or your browser's notes."]},{"heading":"Two-step sign-in","items":["Everyone turns on two-step sign-in in Xevrion (Settings, then Sign-in security).","Turn it on for email, banking and accounts as well, wherever it is offered.","Xevrion asks everyone to sign in again after 12 hours."]},{"heading":"Sharing and reuse","items":["Never share a password, even with a manager or IT support. Nobody genuine will ask for it.","Never reuse a work password anywhere else."]},{"heading":"When a password may have leaked","items":["Change it straight away, from a device you trust.","Tell an owner, so they can check nothing was changed."]},{"heading":"People who join or leave","items":["New people get their own accounts on their first day.","People who leave lose access on their last day."]},{"heading":"Review","items":["An owner reads this policy again every year."]}],"text":"## Why we have this policy\n- Stolen and guessed passwords are a common way into a business. These rules make that much harder.\n\n## Passwords\n- Use a different password for every work account.\n- Make each one long: three random words together is a good way (NCSC advice).\n- Keep them in a password manager, not in a notebook, a file or your browser's notes.\n\n## Two-step sign-in\n- Everyone turns on two-step sign-in in Xevrion (Settings, then Sign-in security).\n- Turn it on for email, banking and accounts as well, wherever it is offered.\n- Xevrion asks everyone to sign in again after 12 hours.\n\n## Sharing and reuse\n- Never share a password, even with a manager or IT support. Nobody genuine will ask for it.\n- Never reuse a work password anywhere else.\n\n## When a password may have leaked\n- Change it straight away, from a device you trust.\n- Tell an owner, so they can check nothing was changed.\n\n## People who join or leave\n- New people get their own accounts on their first day.\n- People who leave lose access on their last day.\n\n## Review\n- An owner reads this policy again every year."}],"outline":["Why we have this policy","Passwords","Two-step sign-in","Sharing and reuse","When a password may have leaked","People who join or leave","Review"]},"incident_response":{"kind":"incident_response","name":"Incident response","purpose":"Who to tell and what to do first when something goes wrong.","version":1,"versions":1,"published":null,"draft":{"n":1,"source":"template","status":"draft","by_name":"Sarah Vale","at":"2026-09-29T09:00:00+00:00","published_at":null,"published_by":null},"acks":{"done":0,"total":0,"missing":[]},"my_ack":false,"history":[{"n":1,"source":"template","status":"draft","by_name":"Sarah Vale","at":"2026-09-29T09:00:00+00:00","published_at":null,"published_by":null,"sections":[{"heading":"Why we have this policy","items":["When something goes wrong, the first hour matters most. This policy says what to do first and who to tell."]},{"heading":"What counts as an incident","items":["A fake email that someone clicked or replied to.","A lost or stolen laptop or phone.","An account someone else signed in to.","Files that are locked or missing.","Anything else that does not look right."]},{"heading":"The first ten minutes","items":["Do not panic and do not try to hide it.","If a computer may be infected, take it off the network and Wi-Fi. Do not wipe it.","Tell an owner, by phone if email may not be safe."]},{"heading":"Who to tell","items":["An owner of Harbour & Vale Logistics leads the response and keeps the record in Xevrion (Security, then Incidents).","For fraud: your bank's fraud line, and Action Fraud on 0300 123 2040 (Police Scotland on 101 in Scotland).","Our IT support and our insurer, if we have cyber cover."]},{"heading":"Personal data and the ICO","items":["If personal data may have been lost or seen, we decide within 72 hours whether to tell the ICO, as UK GDPR asks."]},{"heading":"After the incident","items":["We write down what happened, what we changed and what we will do differently.","We check our backups and passwords again."]},{"heading":"Review","items":["An owner reads this policy again every year, and after any incident."]}],"text":"## Why we have this policy\n- When something goes wrong, the first hour matters most. This policy says what to do first and who to tell.\n\n## What counts as an incident\n- A fake email that someone clicked or replied to.\n- A lost or stolen laptop or phone.\n- An account someone else signed in to.\n- Files that are locked or missing.\n- Anything else that does not look right.\n\n## The first ten minutes\n- Do not panic and do not try to hide it.\n- If a computer may be infected, take it off the network and Wi-Fi. Do not wipe it.\n- Tell an owner, by phone if email may not be safe.\n\n## Who to tell\n- An owner of Harbour & Vale Logistics leads the response and keeps the record in Xevrion (Security, then Incidents).\n- For fraud: your bank's fraud line, and Action Fraud on 0300 123 2040 (Police Scotland on 101 in Scotland).\n- Our IT support and our insurer, if we have cyber cover.\n\n## Personal data and the ICO\n- If personal data may have been lost or seen, we decide within 72 hours whether to tell the ICO, as UK GDPR asks.\n\n## After the incident\n- We write down what happened, what we changed and what we will do differently.\n- We check our backups and passwords again.\n\n## Review\n- An owner reads this policy again every year, and after any incident."}],"outline":["Why we have this policy","What counts as an incident","The first ten minutes","Who to tell","Personal data and the ICO","After the incident","Review"]},"data_retention":{"kind":"data_retention","name":"Data retention","purpose":"How long each kind of record is kept, and how it is deleted.","version":0,"versions":0,"published":null,"draft":null,"acks":{"done":0,"total":0,"missing":[]},"my_ack":false,"history":[],"outline":["Why we have this policy","How long we keep records","Deleting records","Requests from people about their data","Review"]}};
